    "Script": "RoleUserManagement = {
    init: async function (app, container, role) {
        app = app || session.app;
        container = container || $(".component[name=RoleUserManagement]");
        if(!role) { return; }
        api.addToMetaCache([{
            Name: "AppSecurity",
            Types: [
                [meta[AppSecurity/User]],
                [meta[AppSecurity/UserRole]]
            ]
        }]);
        await RoleUserManagement.setupUserGrid(container, role);
    },

	addUsers: async function(e, grid, role) {
        e.preventDefault();
        var userGrid = null;
        var userDialog = new Dialog({title: "[resource_displayname[selectusers]]", width: 800});
        var component = $(grid.gridElement).closest(".component[name=RoleUserManagement]");
        userDialog.template = $("[name=selectusersdialog]", component).html();
        userDialog.events.select = async function(e) {
            e.preventDefault();
			var selected = userGrid.select();
            for(let i = 0; i < selected.length; i++) {
				await api.post("AppSecurity/UserRole", {RoleId: role.Id, UserId: selected[i].Id}).then(() => {
					grid.refresh();
				}).catch((e) => error(e));
			}
			userDialog.events.close();
        };
        userDialog.init(async () => {
            var userData = await model.getDatasource({endpoint: "AppSecurity/User", odataAppend: "?$filter=IsActive eq true"});
            userGrid = new GridWidget($("[name=selectUsersGrid]", userDialog.element), userData);
			userGrid.filterable = true;
			userGrid.groupable = false;
            userGrid.pageable = true;
            userGrid.columns = [
                {selectable: true, width: 50},
                { field: "Id", title: "[resource_displayname[userid]]" },
                { field: "DisplayName", title: "[resource_displayname[displayname]]" },
                { field: "Email", title: "[resource_displayname[email]]" }
            ];
            userGrid.init();
        });
    },

    setupUserGrid: async function(container, role) {
        var users = (await api.get("AppSecurity/UserRole?$filter=RoleId eq " + role.Id + "&$expand=User")).value;
        var ds = new kendo.data.DataSource({ data: users });
        var usersGrid = new GridWidget(container, ds);
        usersGrid.commandWidth = 100;
        usersGrid.columns = [
            { field: "UserId", title: "[resource_displayname[userid]]" },
            { field: "User.Email", title: "[resource_displayname[email]]" }
        ];
        usersGrid.toolbar = "<button name='addUser'><span class='k-icon k-i-plus'></span>[resource_displayname[adduser]]</button><button name='addUsers'><span class='k-icon k-i-plus'></span>[resource_displayname[addusers]]</button>";
        usersGrid.groupable = false;
        usersGrid.editable = false;
        usersGrid.filterable = true;
        usersGrid.commands.push({ name: "delete", icon: "k-i-trash", text: "[resource_displayname[delete]]" });
        usersGrid.dataBound = function() { 
            $("[name=delete]", usersGrid.gridElement).on("click", async function(e) {
		        var item = usersGrid.dataItem($(e.currentTarget).closest("tr"));
                await RoleUserManagement.deleteUser(item, usersGrid);
            });
        };
        await usersGrid.init();
        $("[name=addUser]", usersGrid.gridElement).on("click", async (e) => await RoleUserManagement.addUser(e, role, usersGrid))
        $("[name=addUsers]", usersGrid.gridElement).on("click", async (e) => await RoleUserManagement.addUsers(e, usersGrid, role))
    },

    deleteUser: async function(roleUser, usersGrid) {
        await api.destroy("AppSecurity/UserRole(RoleId=" + roleUser.RoleId + ",UserId='" + roleUser.UserId + "')").then(() => {
            notification.success("[resource_displayname[userdeleted]]");
            usersGrid.refresh();
        }).catch((err) => error(err));
    },

    addUser: async function (e, role, grid) {
        e.preventDefault();
        var model = kendo.observable({ RoleId: role.Id, UserId: "" });
        var addUserDialog = new Dialog({ title: "[resource_displayname[adduser]]", width: 500, height: "auto" });
        var component = $(grid.gridElement).closest(".component[name=RoleUserManagement]");
        addUserDialog.template = $("[name=addUserDialog]", component).html();
        addUserDialog.events.confirm = async function (e) {
            await api.add("AppSecurity/UserRole", model).then(() => {
                notification.success("[resource_displayname[added]]");
                if (role.Users) { role.Users.push({ RoleId: role.Id, UserId:  model.UserId }); }
                addUserDialog.events.close();
                grid.refresh();
            }).catch((err) => error(err));
        };
        addUserDialog.init();
        kendo.bind(addUserDialog.element, model);
    }
}",
